(async () => {
  const base = '/admin/services/public/stores/w5pamplexj';
  const c = await fetch('/internalapi/v1/geography/countries', { credentials: 'include' }).then((r) => r.json()).catch((e) => ({ error: String(e) }));
  const names = (c.data || c).map ? (c.data || c).map((x) => x.name || x.country || x.countryName).filter(Boolean) : [];
  const out = { countries: names.length, first: names.slice(0, 3), sample: {} };
  let done = 0, failed = [];
  for (const n of names) {
    const r = await fetch(`${base}/v0/localization-settings?country=${encodeURIComponent(n)}`, { credentials: 'include' });
    if (r.ok) { const j = await r.json(); done++; if (['Oman', 'United States', 'Germany', 'Japan', 'Saudi Arabia', 'Yemen', 'France', 'China', 'India', 'Brazil'].includes(n)) out.sample[n] = j; } else failed.push([n, r.status]);
  }
  out.done = done; out.failed = failed.slice(0, 20); out.failed_count = failed.length;
  return out;
})()

(async () => {
  const base = '/admin/services/public/stores/w5pamplexj';
  const xsrf = decodeURIComponent((document.cookie.match(/(?:^|; )XSRF-TOKEN=([^;]*)/) || [])[1] || '');
  const H = { accept: 'application/json, text/plain, */*', 'x-xsrf-token': xsrf };
  const c = await fetch('/internalapi/v1/geography/countries', { credentials: 'include' }).then((r) => r.json()).catch((e) => ({ error: String(e) }));
  const names = (c.data || c).map ? (c.data || c).map((x) => x.name || x.country || x.countryName).filter(Boolean) : [];
  const out = { xsrf_found: !!xsrf, countries: names.length, first: names.slice(0, 3), sample: {} };
  let done = 0, failed = [];
  for (const n of names) {
    const r = await fetch(`${base}/v0/localization-settings?country=${encodeURIComponent(n)}`, { credentials: 'include', headers: H });
    if (r.ok) { const j = await r.json(); done++; if (['Oman', 'United States', 'Germany', 'Japan', 'Saudi Arabia', 'Yemen', 'France', 'China', 'India', 'Brazil'].includes(n)) out.sample[n] = j; } else failed.push([n, r.status]);
  }
  out.done = done; out.failed = failed.slice(0, 20); out.failed_count = failed.length;
  return out;
})()
